css:
.d-undo-redo-history{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-undo-redo-history *,.d-undo-redo-history *::before,.d-undo-redo-history *::after{box-sizing:border-box}
.d-undo-redo-history [hidden]{display:none!important}
.d-undo-redo-history .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-undo-redo-history .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-undo-redo-history label{display:block;margin:8px 0}
.d-undo-redo-history input,.d-undo-redo-history select,.d-undo-redo-history textarea,.d-undo-redo-history button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-undo-redo-history input:not([type=checkbox]):not([type=radio]),.d-undo-redo-history select,.d-undo-redo-history textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-undo-redo-history button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-undo-redo-history button:disabled{opacity:.5;cursor:default}
.d-undo-redo-history :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-undo-redo-history [aria-invalid=true]{border-color:var(--warn)!important}
.d-undo-redo-history .d-scroll{max-width:100%;overflow:auto}
.d-undo-redo-history table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-undo-redo-history th,.d-undo-redo-history td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-undo-redo-history caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-undo-redo-history progress{width:100%;accent-color:var(--ink)}
.d-undo-redo-history pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-undo-redo-history h3,.d-undo-redo-history p{margin:8px 0}
.d-undo-redo-history [aria-pressed=true],.d-undo-redo-history [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-undo-redo-history .d-grow{flex:1;min-width:100px}
.d-undo-redo-history summary{cursor:pointer;padding:6px 0}
.d-undo-redo-history ul,.d-undo-redo-history ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{let states=[[]],cursor=0,next=1;const draw=()=>{q('[data-list]').replaceChildren(...states[cursor].map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));q('[data-undo]').disabled=cursor===0;q('[data-redo]').disabled=cursor===states.length-1;say('当前 '+states[cursor].length+' 个镜头');};q('[data-add]').onclick=()=>{const value=states[cursor].concat('样例镜头 '+next++);states=states.slice(0,cursor+1).concat([value]);cursor++;draw();};q('[data-undo]').onclick=()=>{cursor--;draw();};q('[data-redo]').onclick=()=>{cursor++;draw();};draw();})(root, q, qa, say);
}
